export function validateSpecs(){
 const returned=entry.review.filter(r=>r.verdict==="REVISE");assert.equal(returned.length,11);assert.equal(specs.size,11);
 for(const r of returned){const s=specs.get(r.id);assert(s,r.id);assert([3,4].includes(s.options.length));assert.equal(new Set(s.options.map(x=>x[0])).size,s.options.length);assert(s.task.includes("{patientName}"));
  for(const k of ["cues","fairness","suggestions"])assert.equal(s.responses[k].length,r[k].length,r.id+" "+k+" response count");
  for(const k of ["steps","decisive","closest","attack","change","risk"])assert(s[k],r.id+" missing "+k);
 }
 return true;
}
